import csv
import datetime
import os
import random
import subprocess
import sys
import time

log_path, outdir = sys.argv[1], sys.argv[2]


def outputs():
    try:
        return set(os.listdir(outdir))
    except OSError:
        return set()


def log(msg):
    with open(log_path, 'a') as f:
        f.write(f'{datetime.datetime.now()} {msg}\n')


def afterfx_pids():
    out = subprocess.run(['tasklist', '/FI', 'IMAGENAME eq AfterFX.com', '/FO', 'CSV', '/NH'], capture_output=True, text=True).stdout
    return [int(row[1]) for row in csv.reader(out.splitlines()) if len(row) > 1 and row[0].lower() == 'afterfx.com']


spared = None
log('watcher started')
while True:
    for pid in afterfx_pids():
        if pid == spared:
            continue
        if random.random() < 0.5:
            before = outputs()
            log(f'AfterFX.com pid {pid} will be killed when a new file appears in {outdir}')
            while pid in afterfx_pids() and not outputs() - before:
                time.sleep(0.2)
            if pid not in afterfx_pids():
                log(f'AfterFX.com pid {pid} exited before writing a file')
                continue
            r = subprocess.run(['taskkill', '/F', '/PID', str(pid)], capture_output=True, text=True)
            log(f'killed AfterFX.com pid {pid}: {r.stdout.strip()} {r.stderr.strip()}')
        else:
            spared = pid
            log(f'spared AfterFX.com pid {pid}')
    time.sleep(1)
